?/* bubbly coquette typography */
body,
button,
input,
select,
textarea {
  font-family: "Arial Rounded MT Bold",
               "Trebuchet MS",
               sans-serif !important;
}

/* extra cute headings */
h1, h2, h3, h4 {
  font-family: "Arial Rounded MT Bold",
               "Trebuchet MS",
               sans-serif !important;
  font-weight: bold !important;
  letter-spacing: 0.4px !important;
}

